def find_max(lst):
    if not lst:
        raise ValueError('List is empty')
    maximum = lst[0]
    for x in lst[1:]:
        if x > maximum:
            maximum = x
    return maximum

def char_frequency(s):
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1
    return freq

